void unit_test_update_non_head_node_ct_only(void) {
    // Setup: Build a linked list with at least two nodes.
    // The target path is for a non-head node (ptr != NULL && ptr->ID != id) and ct != 0, wt == 0, tat == 0.
    // According to the path, we need:
    // 1. The head node ID does NOT match the target id (so we go into the while loop).
    // 2. The target id exists later in the list (loop exits when found).
    // 3. ct != 0, wt == 0, tat == 0.
    // The path shows that after loop exit, we check (ct != 0) and execute ptr->CT = ct;
    // Then (wt != 0) is false (skip), and (tat != 0) is false (skip).

    int ids[] = {1, 2, 3};
    int ats[] = {0, 1, 2};
    int bts[] = {5, 4, 3};
    int priorities[] = {1, 2, 3};
    int size = 3;

    struct node *root = helper_build_process_queue(ids, ats, bts, priorities, size);
    TEST_ASSERT_NOT_NULL(root);

    // Verify initial CT values are zero (as per insert function).
    struct node *ptr = root;
    while (ptr != NULL) {
        TEST_ASSERT_EQUAL_INT(0, ptr->CT);
        ptr = ptr->next;
    }

    // Test: Update the second node (ID=2) with ct=100, wt=0, tat=0.
    update(&root, 2, 100, 0, 0);

    // Assertions: Check that only the CT of node with ID=2 is updated.
    ptr = root;
    while (ptr != NULL) {
        if (ptr->ID == 2) {
            TEST_ASSERT_EQUAL_INT(100, ptr->CT);
            TEST_ASSERT_EQUAL_INT(0, ptr->WT);   // Should remain zero.
            TEST_ASSERT_EQUAL_INT(0, ptr->TAT);  // Should remain zero.
        } else {
            TEST_ASSERT_EQUAL_INT(0, ptr->CT);   // Other nodes unchanged.
        }
        ptr = ptr->next;
    }

    // Cleanup
    helper_cleanup_process_queue(&root);
    TEST_ASSERT_NULL(root);
}

